Lemma FlatBuf_rheap_pres : forall LB SP m m' fb FB ds,
  FlatBuf LB m fb FB ds -> rheap_pres LB SP m m' -> rclient_range LB SP fb SZ_FB -> FlatBuf LB m' fb FB ds.
Proof.
  intros LB SP m m' fb FB ds (C & OK & SZ & BLK) HP CR. split; [| split; [exact OK | split; [exact SZ |]]].
  - eapply rheap_pres_rw_cells; [exact HP | exact C |]. unfold FlatBufCells, SZ_FB in *. cbn. exact CR.
  - intros NE. destruct (BLK NE) as (pre & junk & B). exists pre, junk.
    eapply rheap_pres_rw_cells; [exact HP | exact B |].
    destruct OK as [E | (p & IN & RR & CP & S1 & S2)]; [exfalso; exact (NE E) |].
    right; right. exists (p, fb_begin FB, fb_cap FB). split; [exact IN |]. cbn.
    pose proof B as [[WF _] _]. cbn in WF. unfold fb_cap, fb_size, zlength in *. lia.
Qed.

Lemma FlatBuf_LB_mono : forall LB LB' m fb FB ds,
  FlatBuf LB m fb FB ds -> (forall b, In b LB -> In b LB') -> FlatBuf LB' m fb FB ds.
Proof.
  intros LB LB' m fb FB ds (C & OK & SZ & BLK) HL. split; [exact C | split; [| split; [exact SZ | exact BLK]]].
  destruct OK as [E | (p & IN & R)]; [left; exact E | right]. exists p. split; [apply HL; exact IN | exact R].
Qed.
