Lemma fbp_munch_client : forall lo SP fb FB, hceil <= lo ->
  Forall (fun iv : Z * Z => (hceil <= fst iv /\ snd iv <= SP) \/ (forall a, fst iv <= a < snd iv -> rin_ivs (fb_X fb FB) a))
         [(lo, SP); (fb, fb + SZ_FB); (fb_begin FB, fb_end FB)]%Z.
Proof.
  intros lo SP fb FB CE. unfold fb_X.
  constructor; [left; cbn; lia |]. constructor; [right; intros aa Ha; cbn [rin_ivs fst snd]; clear - Ha; qtauto |]. constructor; [right; intros aa Ha; cbn [rin_ivs fst snd]; clear - Ha; qtauto |]. constructor.
Qed.

